    formulaMr: 'समासातील कोणत्या पदाला अधिक महत्त्व आहे यावरून समासाचे चार मुख्य प्रकार ठरतात.',
    definition: 'Samas (Compound words) is the process of joining two words together for brevity. Types are determined by which component word is dominant.',
    definitionMr: 'शब्दांमधील परस्पर संबंध दाखविणारे विभक्ती प्रत्यय किंवा शब्द गाळून जो एक जोडशब्द तयार होतो त्यास \'सामासिक शब्द\' आणि या प्रक्रियेस \'समास\' म्हणतात.',
    keyPoints: [
      '1. Avyayībhāv Samas (अव्ययीभाव समास): 1st word is primary and is an indeclinable (अव्यय). Eg: प्रतिदिन, यथाशक्ती, आजन्म, घरोघरी, गावोगावी, बिनधास्त, दररोज.',
      '2. Tatpurush Samas (तत्पुरुष समास): 2nd word is primary. Subtypes: Vibhakti Tatpurush (राजपुत्र), Karmadharaya (नीलकमल, रक्तचंदन), Dvigu (त्रिभुवन, नवरात्र), Madhyampadlopī (कांदेपोहे, पुरणपोळी), Nan-Tatpurush (अनादर), Upapad (पंकज, ग्रंथकार).',
      '3. Dvandva Samas (द्वंद्व समास): Both 1st and 2nd words are equally primary. Subtypes: Itaretar (\'आणि/व\': आई-वडील, राम-लक्ष्मण), Vaikalpik (\'किंवा/अथवा\': खरे-खोटे, बरे-वाईट), Samāhār (\'इत्यादी/वगैरे\': भाजीपाला, मीठभाकर, चहापाणी).',
      '4. Bahuvrīhi Samas (बहुव्रीही समास): Neither word is primary; denotes a 3rd entity having that characteristic. Eg: लंबोदर (गणपती), नीलकंठ (शंकर), चक्रपाणी (विष्णू), दशानन (रावण), निरस.'
    ],
    keyPointsMr: [
      '१. अव्ययीभाव समास: पहिले पद महत्त्वाचे असून संपूर्ण शब्द क्रियाविशेषणासारखा कार्य करतो (उदा. आजन्म, प्रतिदिन, यथाशक्ती, घरोघरी). उपसर्ग: आ, यथा, प्रति (संस्कृत); बे, बिन, गैर, हर, दर (फारसी); द्विरुक्ती (घरोघरी, गल्लोगल्ली).',
      '२. तत्पुरुष समास: दुसरे पद महत्त्वाचे. उपप्रकार:\n • विभक्ती तत्पुरुष: सुखप्राप्त (सुखाला प्राप्त - द्वितीया), राजपुत्र (राजाचा पुत्र - षष्ठी).\n • कर्मधारय: विशेषण + नाम (उदा. नीलकमल, रक्तचंदन, चंद्रमुख).\n • द्विगु: पहिले पद संख्याविशेषण असून समुदायाचा बोध होतो (उदा. नवरात्र, त्रिभुवन, पंचवटी).\n • मध्यमपदलोपी: मधल्या शब्दांचा लोप (उदा. कांदेपोहे = कांदे घालून केलेले पोहे, पुरणपोळी).\n • नञ् तत्पुरुष: पहिले पद नकारार्थी (अनादर, नापसंत, अहिंसा).\n • उपपद/कृदंत: दुसरे पद धातूसाधित (पंकज, जलद, कुंभार).\n • अलुक् तत्पुरुष: विभक्ती प्रत्ययाचा लोप न होणारा (युधिष्ठिर, पंकेरुह).',
      '३. द्वंद्व समास: दोन्ही पदे महत्त्वाची. उपप्रकार:\n • इतरेतर: विग्रह करताना \'आणि, व\' (उदा. आई-वडील, बहीण-भाऊ).\n • वैकल्पिक: विग्रह करताना \'किंवा, अथवा, वा\' (उदा. बरे-वाईट, पाप-पुण्य).\n • समाहार: त्या वस्तूंसह त्याच जातीच्या इतर वस्तूंचा समावेश (उदा. भाजीपाला, चहापाणी, मीठभाकर).',
      '४. बहुव्रीही समास: दोन्ही पदे प्रमुख नसून तिसऱ्याच घटकाचा बोध होतो (उदा. गजानन, चक्रपाणी, पीतांबर, लंबोदर).'
    ],
    examples: [
      {
        sentence: 'कांदेपोहे (कांदे घालून तयार केलेले पोहे) = मध्यमपदलोपी तत्पुरुष समास',
        isCorrect: true,
        explanation: 'The intermediary relational words "घालून तयार केलेले" are omitted in the compound word. Hence Madhyampadlopī.',
        explanationMr: 'दोन पदांमधील परस्पर संबंध दाखविणारे मधले शब्द गाळले जातात, म्हणून याला मध्यमपदलोपी तत्पुरुष समास म्हणतात.'
      },
      {
        sentence: 'चौकोन (चार आहेत कोन ज्याला अशी आकृती) = बहुव्रीही समास',
        isCorrect: true,
        explanation: 'MPSC Standard: Though \'चार\' is a number, \'चौकोन\' denotes a specific 3rd geometric entity (quadrilateral), so it is Bahuvrīhi in MPSC questions.',
        explanationMr: 'जरी पहिले पद संख्या असले तरी चौकोन म्हणजे चार कोनांचा समूह नसून विशिष्ट भूमितीय आकृतीचा बोध होतो = बहुव्रीही समास.'
      }
    ],
    exceptions: [
      'पीतांबर शब्दाचे दोन समास होतात: "पीत असे अंबर" (कर्मधारय) आणि "पीत आहे अंबर ज्याचे असा तो - विष्णू" (बहुव्रीही). विग्रहावरून समास ठरतो!'
    ],
    exceptionsMr: [
      'MPSC ट्रॅप: शब्दाचा विग्रह कसा केला आहे यावर समास ठरतो! उदा. \'नीलकंठ\' = निळा असा कंठ (कर्मधारय); निळा आहे कंठ ज्याचा तो शंकर (बहुव्रीही).'
    ],
    examTip: 'पद प्राधान्य सुपर-ट्रिक:\n• १ ले पद महत्त्वाचे ➔ अव्ययीभाव\n• २ रे पद महत्त्वाचे ➔ तत्पुरुष\n• दोन्ही (१+२) पदे महत्त्वाची ➔ द्वंद्व\n• तिसरेच पद महत्त्वाचे ➔ बहुव्रीही',
    examTipMr: 'MPSC शॉर्टकट:\n१. पहिले पद प्रधान = अव्ययीभाव\n२. दुसरे पद प्रधान = तत्पुरुष\n३. दोन्ही पदे प्रधान = द्वंद्व\n४. दोन्ही गौण, ३ रेच पद = बहुव्रीही',
