    categoryMr: 'मराठी अलंकार (उपमा, उत्प्रेक्षा, रूपक, व्यतिरेक, श्लेष, अपन्हुती)',
    title: 'Alankar Identification Formulas: Upama, Utpreksha, Rupak, Vyatirek, Shlesh, Apanhuti',
