    title: 'Rules of "Either...or", "Neither...nor", "Not only...but also", and "Or / Nor"',
    titleMr: '"Either...or", "Neither...nor", "Not only...but also" नियम',
    formula: 'Neither S1 nor S2 + Verb (agrees with S2 / the nearer subject)',
    formulaMr: 'क्रियापद हे नेहमी जवळच्या (दुसऱ्या) कर्त्यानुसार (Nearer Subject) ठरते.',
    definition: 'When two subjects are joined by "either...or", "neither...nor", "not only...but also", or "or/nor", the verb must agree in person and number with the subject NEAREST to it.',
    definitionMr: 'जेव्हा दोन कर्ते "either...or", "neither...nor", "not only...but also" किंवा "or / nor" ने जोडलेले असतात, तेव्हा क्रियापद नेहमी त्याच्या सर्वात जवळ असणाऱ्या (दुसऱ्या) कर्त्यानुसार बदलते.',
    keyPoints: [
      'If the second (nearer) subject is singular, the verb MUST be singular.',
      'If the second (nearer) subject is plural, the verb MUST be plural.',
      'Rule of Proximity applies in inverted interrogative sentences: the verb agrees with the first subject because it is closest to the verb (e.g. "Has either of them arrived?").'
    ],
    keyPointsMr: [
      '१. क्रियापदाच्या सर्वात जवळ असलेला कर्ता एकवचनी असेल तर क्रियापद एकवचनी (Singular) वापरावे.',
      '२. जवळचा कर्ता अनेकवचनी असेल तर क्रियापद अनेकवचनी (Plural) वापरावे.',
      '३. परीक्षांमध्ये बऱ्याचदा पहिल्या कर्त्याकडे लक्ष वेधून फसवले जाते, परंतु लक्ष नेहमी \'nor\' किंवा \'or\' नंतरच्या कर्त्यावर असावे.'
    ],
