    examTip: 'Passive Voice Elimination Trick: Check options for:\n1. Is the verb V3? (If not, eliminate!)\n2. If question is Continuous (-ing), does option have "being"? (If not, eliminate!)\n3. If question is Perfect, does option have "been"? (If not, eliminate!)',
    examTipMr: 'पर्याय बाद करण्याची MPSC क्लृप्ती:\n१. पर्यायात V3 नाही? ➔ पर्याय बाद!\n२. प्रश्नात -ing (Continuous) आहे आणि पर्यायात being नाही? ➔ पर्याय बाद!\n३. प्रश्नात has/have/had आहे आणि पर्यायात been नाही? ➔ पर्याय बाद!',
