    definition: 'Article "An" is used before singular countable nouns beginning with a VOWEL SOUND. Article "A" is used before words beginning with a CONSONANT SOUND, irrespective of spelling.',
    definitionMr: '\'An\' चा वापर स्वराच्या उच्चाराने (Vowel Sound) सुरू होणाऱ्या नामांच्या आधी केला जातो, तर \'A\' चा वापर व्यंजनाच्या उच्चाराने (Consonant Sound) सुरू होणाऱ्या नामांच्या आधी केला जातो. इथे स्पेलिंग महत्त्वाचे नसून तोंडून निघणारा पहिला ध्वनी महत्त्वाचा असतो.',
