      '३. संक्षिप्त रूपे (Abbreviations): उच्चार स्वराने सुरू झाल्यास \'An\' लागते:\n • An MLA (उच्चार: \'ए\'म.एल.ए.)\n • An FIR, an SP, an MBA, an MP, an X-ray.'
