    definition: 'Definite article "The" specifies particular entities, unique objects, and geographical features. Omitting articles where not required is equally tested in MPSC.',
    definitionMr: 'विशिष्ट घटकांचा उल्लेख करताना किंवा निसर्गातील अद्वितीय गोष्टी, नद्या, पर्वत रांगा, सुपरलेटिव्ह डिग्री यांच्या आधी \'The\' चा वापर होतो. तसेच ज्या ठिकाणी उपपद वापरणे वर्ज्य आहे (Omission) त्यावरही MPSC प्रश्न विचारते.',
