      '३. Beside (बाजूला / शेजारी): Sit beside me (माझ्या शेजारी बस).',
      '४. Besides (च्या व्यतिरिक्त / शिवाय): Besides a car, he has a bike (कारशिवाय त्याच्याकडे बाईकही आहे).',
