    titleMr: '"No sooner...than", "Hardly...when" आणि "Lest...should" नियम',
    formula: 'No sooner + did/had + Sub + V1/V3 + THAN | Hardly/Scarcely + had + Sub + V3 + WHEN | Lest + Sub + SHOULD',
