    definition: 'Correlative conjunctions that express immediate successive actions or precautions require fixed pairing and inverted word order when beginning a sentence.',
    definitionMr: 'दोन घटना एकापाठोपाठ लगेच घडल्या हे दर्शविण्यासाठी "No sooner...than" आणि "Hardly...when" चा वापर होतो. वाक्याच्या सुरुवातीला हे शब्द आल्यास सहाय्यकारी क्रियापद कर्त्याच्या आधी येते (Inversion).',
    keyPoints: [
      'Pairing 1: "No sooner" is ALWAYS paired with "THAN" (NEVER with "then", "when", or "that").',
      'Inversion for No sooner: No sooner + did + S + V1 + than... OR No sooner + had + S + V3 + than...',
      'Pairing 2: "Hardly" and "Scarcely" are ALWAYS paired with "WHEN" (or "before", NEVER with "than").',
      'Inversion for Hardly: Hardly + had + S + V3 + when...',
      'Pairing 3: "Lest" means "for fear that" or "otherwise". It is ALWAYS followed by the modal "SHOULD" (or bare subjunctive), and it NEVER takes "not" because it is already negative!'
    ],
    keyPointsMr: [
      '१. No sooner ची जोडी नेहमी \'THAN\' सोबतच असते. परीक्षेत \'then\' किंवा \'when\' देऊन फसवले जाते, जे चूक आहे.',
      '२. No sooner ने वाक्याची सुरुवात झाल्यास Auxiliary Verb कर्त्याच्या आधी येते:\n • No sooner did he see the police than he ran away. (did + V1)\n • No sooner had he seen the police than he ran away. (had + V3)',
      '३. Hardly किंवा Scarcely ची जोडी नेहमी \'WHEN\' सोबत असते (कधीही than येत नाही!).',
      '४. Lest चा नियम: Lest नंतर येणाऱ्या वाक्यात नेहमी \'SHOULD\' येते आणि Lest स्वतःच नकारार्थी असल्याने त्यानंतर कधीही \'NOT\' वापरता येत नाही!'
    ],
