    examTipMr: 'MPSC च्या ३ जोड्या पाठ करा:\n१. No sooner ➔ THAN (than चे स्पेलिंग पाहा, then नाही!)\n२. Hardly / Scarcely ➔ WHEN\n३. Lest ➔ SHOULD (not लावायचा नाही!)',
