        explanationMr: 'बरोबर! हवामानासाठी "It" हा स्वतंत्र कर्ता सुरुवातीला दिल्याने वाक्य व्याकरणदृष्ट्या परिपूर्ण आहे. (वादळी रात्र असल्याने कोळ्यांनी अरबी समुद्रात न जाण्याचा निर्णय घेतला.)'
