    examTipMr: 'MPSC क्लृप्ती: आधी "but also" च्या पुढे पहा काय आहे (नाम आहे की क्रियापद). जे पद "but also" च्या पुढे असेल, अगदी तसेच पद "not only" च्या पुढे आणून ठेवा; क्रियापद दोन्हीच्या बाहेर काढा!',
