        explanationMr: 'बरोबर! "Forbade" (मनाई केली) या नकारार्थी क्रियापदानंतर "to use" आले असून "not" लावलेला नाही. (मतदान केंद्राध्यक्षानी मतदान केंद्रात मोबाईल वापरण्यास मनाई केली.)'
