    examTipMr: 'MPSC २ सेकंदांची क्लृप्ती:\n१. वस्तू किंवा बाहेरील व्यक्ती असल्यास ➔ OLDER THAN.\n२. सख्खा भाऊ/बहीण असल्यास ➔ ELDER TO (वाक्यात "elder than" दिसल्यास "than" खोडा आणि "to" लावा)!',
