        explanationMr: 'बरोबर! "It is I" मध्ये प्रथमा विभक्ती असून "I" ला अनुसरून "who" नंतर "am" हे क्रियापद १००% व्याकरणाच्या नियमानुसार अचूक आहे. (सेमिनारच्या समन्वयाची जबाबदारी माझीच आहे.)'
