    examTipMr: 'MPSC २ कलमी सुवर्ण नियम:\n१. "WHO" च्या आधी पहा: I, He, She, They च हवे (me, him, them दिसल्यास खोडा)!\n२. "WHO" च्या नंतर पहा: क्रियापद त्या सर्वनामानुसार हवे (I ➔ am, You ➔ are, He ➔ is)!',
