        explanationMr: 'बरोबर! "Looking forward to" नंतर "taking" (V-ing) चा वापर नियमानुसार १००% अचूक आहे. (दुष्काळग्रस्त उपविभागाचा कार्यभार स्वीकारण्यासाठी तो तरुण अधिकारी उत्सुक आहे.)'
