        explanationMr: 'बरोबर! ग्रंथपालाने प्राचीन हस्तलिखिते टेबलावर ठेवली. हस्तलिखिते हे कर्म असल्याने सकर्मक क्रियापद "laid" चा वापर बरोबर आहे.'
