    examTipMr: 'MPSC १ सेकंदाची परीक्षा ट्रिक:\nवाक्यात शब्दांची जागा तपासा:\n• जर "The all..." दिसले ➔ चूक! उलटे करून "All the..." करा!\n• जर "Whole the..." दिसले ➔ चूक! उलटे करून "The whole..." करा!',
